  private final List<Node> nodes=new ArrayList<Node>();private final boolean[][] seen=new boolean[16][11];private final Random rnd=new Random(2608L);private final ArcadeFx fx=new ArcadeFx();
  private int page=0,hx=2,hy=8,fromX=2,fromY=8,toX=2,toY=8,rivalX=13,rivalY=2,day=1,week=1,moves=5,maxMoves=5,score;
  private int iron=5,cement=4,tools=1,gold=220,blueprints,contracts,artifacts,morale=72,luck=4,shop=1,weld=1,truck=0;
  private int crew0=7,crew1=3,crew2=1,reserve0=4,reserve1=2,reserve2=1,rivalPower=13;
  private int ownHp=220,enemyHp=200,enemyMax=200,guard,selectedArmy,enemyType,turn,combatSource=-1;private float moveT=1,clock,combatAnim,flash;private boolean moving;
  private final RectF up=new RectF(770,358,844,426),down=new RectF(770,432,844,504),left=new RectF(694,432,766,504),right=new RectF(848,432,922,504);
  private final RectF townBtn=new RectF(692,272,804,338),combatBtn=new RectF(812,272,944,338),endTurn=new RectF(704,348,940,408),mapBtn=new RectF(742,432,944,500);
  private final RectF build0=new RectF(78,398,250,464),build1=new RectF(274,398,446,464),build2=new RectF(470,398,642,464),recruit0=new RectF(76,294,248,360),recruit1=new RectF(272,294,444,360),recruit2=new RectF(468,294,640,360);
